// `yad docs list|build|deploy|sync` — the build/deploy/staleness mechanics for the interactive
// documentation sites generated by the yad-docs / yad-docs-overview skills. The CONTENT generation
// (reading epic/architecture/contract/ui/stories → writing src/data/*.ts and theming index.css) is
// the AI step inside those skills; this module only does the mechanical parts: npm build (a
// subprocess, like yad-spec shelling out to Repomix), the platform Pages wiring (reusing platform.mjs),
// and the manifest-hash staleness check (reusing the head-sha idea from repo.mjs). It NEVER touches
// epic state, approvals, or the contract lock — docs are an output enrichment, not a gate.
//
// Pure mapping fns (deployTargetFromProduct / siteBasePath / docsArtifactHash / docsStale / pagesWorkflow)
// are exported for unit tests; the side-effecting runDocs orchestrates them.
import path from 'node:path';
import fs from 'node:fs';
import { createHash } from 'node:crypto';
import { c, log, ok, info, warn, hand, fail, readJSON, runLauncher, has, exists } from './lib.mjs';
import { PROJECT_FILES } from './manifest.mjs';
import { detectPlatform, platformReady } from './platform.mjs';
import { gitHead } from './setup.mjs';
import { contractSurfaceHash } from './epic-state.mjs';

// ---- registry + site locations ------------------------------------------------------------------
function loadDocs(root) {
  const regPath = path.join(root, PROJECT_FILES.docsConfig);
  return { regPath, docs: readJSON(regPath, null) };
}

// Per-epic site lives beside the epic artifacts; the overview is project-level under docs/.
export function siteDir(root, { epic, overview } = {}) {
  if (overview) return path.join(root, 'docs/sdlc-site');
  return path.join(root, 'epics', epic, 'docs-site');
}
export function manifestPath(root, { epic, overview } = {}) {
  if (overview) return path.join(siteDir(root, { overview }), '.docs-build.json');
  return path.join(root, 'epics', epic, '.sdlc/docs-build.json');
}

// ---- pure: platform/target + base path ----------------------------------------------------------
// hub.json platform -> the default Pages target (github-pages | gitlab-pages | none/build-only).
export function deployTargetFromProduct(productConfig = {}) {
  const platform = productConfig?.platform || detectPlatform(productConfig?.git_url || '');
  if (platform === 'github') return 'github-pages';
  if (platform === 'gitlab') return 'gitlab-pages';
  return 'none';
}

// The Vite `base` for one site: join the project base path (from docs.json) with the per-site
// subpath. The overview SPA mounts under `app/` so the hand-maintained report.html can own the
// Pages root (`<base>/`) as the main documentation; per-epic sites nest under epics/<id>/. Always a
// leading+trailing slash so it works as a Vite base and a router basename.
export function siteBasePath(docs = {}, { epic, overview } = {}) {
  const root = (docs.basePath || '/').replace(/\/+$/, '') || '';
  const sub = overview ? '/app' : epic ? `/epics/${epic}` : '';
  const joined = `${root}${sub}`.replace(/\/+/g, '/');
  return joined ? `${joined.replace(/\/$/, '')}/` : '/';
}

// ---- pure: staleness ----------------------------------------------------------------------------
// The artifacts whose content a per-epic site is generated from (any that exist contribute).
// contract.md is deliberately EXCLUDED here: it is folded in via its CONTRACT-SURFACE block hash
// (docsArtifactHash's `extra`), so docs-staleness tracks the same locked surface as the contract
// lock — non-surface prose edits to contract.md don't needlessly mark the docs stale.
export function docsArtifactFiles(root, epic) {
  const epicRoot = path.join(root, 'epics', epic);
  const flat = ['epic.md', 'architecture.md', 'ui-design.md', 'DESIGN.md', 'test-cases.md']
    .map((f) => path.join(epicRoot, f));
  const storiesDir = path.join(epicRoot, 'stories');
  const stories = exists(storiesDir)
    ? fs.readdirSync(storiesDir).filter((f) => f.endsWith('.md')).sort().map((f) => path.join(storiesDir, f))
    : [];
  return [...flat, ...stories].filter(exists).sort();
}

// sha256 over the (sorted) artifact files' bytes plus an optional `extra` string (the contract
// surface hash) — the content baseline a site was built from. Deterministic: the file list is
// sorted and each file is length-prefixed so concatenation is unambiguous (a + bc never collides
// with ab + c).
export function docsArtifactHash(files = [], extra = '') {
  const h = createHash('sha256');
  for (const f of [...files].sort()) {
    const buf = fs.readFileSync(f);
    h.update(`${path.basename(f)}:${buf.length}\n`);
    h.update(buf);
  }
  if (extra) h.update(`\ncontract-surface:${extra}`);
  return 'sha256:' + h.digest('hex');
}

// Current HEAD sha per repo the epic touches (mirrors repo.mjs head-sha staleness).
export function repoHeadsFor(root, repos = [], registry = { repos: [] }) {
  const out = {};
  for (const name of repos) {
    const entry = (registry.repos || []).find((r) => r.name === name);
    if (!entry) continue;
    out[name] = gitHead(path.resolve(root, entry.path)) || null;
  }
  return out;
}

// The version of the docs shell a per-epic site is copied from: the `version` in the template's own
// package.json. It moves only when the shell changes — cli/test.mjs pins it to a fingerprint of the
// template, so an edit to the shell cannot land without a new version.
//
// It replaced the yad CLI VERSION here, which moves on EVERY release: each publish marked every docs site
// "doc shell upgraded" whether or not the shell had changed. A manifest written before this carries that
// CLI version as `templateVersion`, which is never compared. What such a manifest is read as instead is
// LEGACY_SHELL_VERSION, below.
//
// Read when a freshness check asks, never at import: every `yad` command loads this module, and a copy of
// the CLI without `skills/` beside it (a test harness, a partial checkout) must still start. No template
// found means no shell version, so that one comparison is skipped.
export function shellVersion() {
  try {
    return JSON.parse(fs.readFileSync(new URL('../skills/yad-docs/templates/app/package.json', import.meta.url), 'utf8')).version || null;
  } catch { return null; }
}

// The shell version every site built before `shellVersion` existed was built on. Exact, not a guess: the
// template's package.json has said `0.0.0` since its first commit, so a manifest that records only the old
// `templateVersion` came from that shell. Reading it this way reports nothing today, and still reports
// the first real shell upgrade — ignoring the old manifest instead would have missed that for ever,
// because only a skill rewrites a manifest and nothing prompts one to.
export const LEGACY_SHELL_VERSION = '0.0.0';

// Compare a build manifest to the current world; list the concrete reasons it is stale.
export function docsStale(manifest, { artifactHash, repoHeads = {}, shellVersion } = {}) {
  const reasons = [];
  if (!manifest) return { stale: true, reasons: ['never built'] };
  if (artifactHash && manifest.artifactHash && artifactHash !== manifest.artifactHash) {
    reasons.push('authored artifacts changed');
  }
  for (const [repo, head] of Object.entries(repoHeads)) {
    const was = (manifest.repoHeads || {})[repo];
    if (head && was && head !== was) reasons.push(`repo ${repo} HEAD advanced`);
  }
  const builtOn = manifest.shellVersion || (manifest.templateVersion ? LEGACY_SHELL_VERSION : null);
  if (shellVersion && builtOn && shellVersion !== builtOn) {
    reasons.push(`doc shell upgraded (${builtOn} → ${shellVersion})`);
  }
  return { stale: reasons.length > 0, reasons };
}

// ---- pure: the Pages CI workflow (committed by `yad docs sync --wire`) ---------------------------
// GitHub Actions deploy-pages, or a GitLab `pages` job. Both assemble a single `public/` tree: the
// hand-maintained report.html owns the root (`<base>/` — the main documentation), the overview SPA
// mounts under `app/`, and every per-epic site nests under `epics/<id>/` — matching siteBasePath
// (overview at `<base>/app/`, epics at `<base>/epics/EP-<slug>/`). A concurrency group prevents the
// deploy from retriggering. The shared shell script keeps the two platforms byte-for-byte aligned.
// A site that fails to build fails the run: CI runs the script under `set -e`, which does not stop on a
// failure inside an `&&` chain, so a failed site used to be silently left out while the deploy still went
// green — yadflow's own site lost its root page that way for days. Each chain ends in `|| failed=…`, so
// every site is still tried (as `yad docs build` does) and the last line fails the run, naming them all.
// A red run uploads nothing, so the last good deployment stays live.
// A YAML single-quoted scalar: a quote inside is written twice, and nothing else is escaped (a backslash
// is literal). The shell's '\'' is not YAML — it would make GitLab reject the whole pipeline.
export const yamlQuoted = (s) => `'${String(s).replace(/'/g, "''")}'`;
const PAGES_FAIL_LINE = 'yad-docs: these sites did not build, so nothing is deployed:';
const BUILD_PUBLIC = [
  'mkdir -p public',
  'failed=',
  'if [ -d docs/sdlc-site ]; then (cd docs/sdlc-site && npm ci && npm run build) && mkdir -p public/app && cp -r docs/sdlc-site/dist/. public/app/ && cp docs/sdlc-site/public/report.html public/index.html && cp docs/sdlc-site/public/report.html public/report.html || failed="$failed docs/sdlc-site"; fi',
  'if [ -d docs/tutorial-site ]; then (cd docs/tutorial-site && npm ci && npm run build) && mkdir -p public/tutorial && cp -r docs/tutorial-site/dist/. public/tutorial/ || failed="$failed docs/tutorial-site"; fi',
  'for d in epics/*/docs-site; do [ -d "$d" ] || continue; id=$(basename "$(dirname "$d")"); (cd "$d" && npm ci && npm run build) && mkdir -p "public/epics/$id" && cp -r "$d/dist/." "public/epics/$id/" || failed="$failed $d"; done',
  `if [ -n "$failed" ]; then echo "${PAGES_FAIL_LINE}$failed" >&2; exit 1; fi`,
];
// The platform `--wire` writes for: the Product's docs target, GitHub unless it says GitLab.
export const wiredPagesPlatform = (docs) => (docs?.target === 'gitlab-pages' ? 'gitlab' : 'github');
// Does a wired Pages workflow fail its deploy when a site fails to build? Read by `yad doctor`. Only this
// line is looked for — not the whole file — so a Dependabot pin bump or an edit elsewhere is not news.
export const pagesWorkflowFailsOnBuild = (text) => text.includes(PAGES_FAIL_LINE);
export function pagesWorkflow(platform) {
  if (platform === 'gitlab') {
    return `# yad-managed — built by \`yad docs sync --wire\`. include it from .gitlab-ci.yml:
#   include: { local: .gitlab/ci/yad-docs.yml }
# Edit the skill, not this file.
pages:
  stage: deploy
  # Set the YAD_RUNNER_TAGS / YAD_NODE_VERSION CI/CD variables to route this job to a tag-locked runner or
  # change its Node line; a shell-executor runner ignores \`image:\` and needs Node on its host.
  tags: [$YAD_RUNNER_TAGS]
  image: node:\${YAD_NODE_VERSION}
  variables:
    YAD_NODE_VERSION: "22"
  rules:
    - if: '$CI_COMMIT_BRANCH == $CI_DEFAULT_BRANCH'
  script:
${BUILD_PUBLIC.map((l) => `    - ${yamlQuoted(l)}`).join('\n')}
  artifacts:
    paths: [public]
  resource_group: pages
`;
  }
  return `# yad-managed — built by \`yad docs sync --wire\`. Edit the skill, not this file.
name: yad-docs
on:
  push:
    branches: [main, master]
  workflow_dispatch:
permissions:
  contents: read
concurrency:
  group: yad-docs-pages
  cancel-in-progress: true
jobs:
  build-deploy:
    runs-on: ubuntu-latest
    permissions:
      contents: read
      pages: write # publish the site
      id-token: write # prove to Pages that this run is the deploy
    environment:
      name: github-pages
      url: \${{ steps.deployment.outputs.page_url }}
    steps:
      - uses: actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1 # v7.0.1
      - uses: actions/setup-node@949feb2413d6458794dcd2491c4babbbce0c15c1 # v7.1.0
        with:
          node-version: 20
      - name: Build the overview + per-epic sites into ./public
        run: |
${BUILD_PUBLIC.map((l) => `          ${l}`).join('\n')}
      - uses: actions/configure-pages@45bfe0192ca1faeb007ade9deae92b16b8254a0d # v6.0.0
      - uses: actions/upload-pages-artifact@fc324d3547104276b827a68afc52ff2a11cc49c9 # v5.0.0
        with:
          path: public
      - id: deployment
        uses: actions/deploy-pages@368f82528645a54fb793d4d04e342629a3f51346 # v5.0.1
`;
}
export function pagesWorkflowPath(platform) {
  return platform === 'gitlab' ? '.gitlab/ci/yad-docs.yml' : '.github/workflows/yad-docs.yml';
}

// ---- build (subprocess) -------------------------------------------------------------------------
// Builds one site and says what happened: `{ site, built, error }`, where `error` is why it was not
// built (null when it was). Every caller — build, deploy, sync --refresh — reads that one row, so a
// failure is said the same way on each path. A failure sets exit 1 and is a `fail` with its `hand`
// right under it: under --json that pair IS the refusal, and a later `hand` (deploy's "no Pages
// platform") can never become a failed build's hint. The one miss that is only a warning is npm not on
// PATH for a deploy or a refresh, which the CI workflow builds on push (`npmOptional`).
function buildSite(root, t, { npmOptional = false } = {}) {
  const dir = siteDir(root, t);
  const rel = path.relative(root, dir) || '.';
  const site = label(t);
  const failed = (error, next) => {
    fail(error);
    hand(next);
    process.exitCode = 1;
    return { site, built: false, error };
  };
  if (!exists(dir)) return failed(`${site}: no generated site at ${rel}`, `run the ${t.overview ? 'yad-docs-overview' : 'yad-docs'} skill first`);
  if (!has('npm')) {
    const error = `${site}: npm not on PATH — cannot build`;
    if (!npmOptional) return failed(error, 'install npm (or put it on PATH), then run the command again');
    warn(`${error}; the CI workflow will build on push`);
    return { site, built: false, error };
  }
  const install = exists(path.join(dir, 'package-lock.json')) ? ['ci'] : ['install'];
  const again = 'fix the error npm printed above, then run the command again';
  log(`  ${c.dim('$')} npm ${install[0]} ${c.dim(`(${rel})`)}`);
  if (!runLauncher('npm', install, { cwd: dir, stdio: 'inherit' }).ok) return failed(`${site}: npm ${install[0]} failed`, again);
  if (!runLauncher('npm', ['run', 'build'], { cwd: dir, stdio: 'inherit' }).ok) return failed(`${site}: npm run build failed`, again);
  ok(`built ${site} ${c.dim('→ ' + path.relative(root, path.join(dir, 'dist')))}`);
  return { site, built: true, error: null };
}

// ---- orchestration ------------------------------------------------------------------------------
export async function runDocs(root, { action = 'list', epic, overview, sync } = {}) {
  const { docs } = loadDocs(root);
  const targets = overview ? [{ overview: true }] : epic ? [{ epic }] : enumerateSites(root);

  if (action === 'list') {
    if (!docs) { warn('no docs target connected (.sdlc/docs.json) — run yad-connect-docs'); }
    else {
      log(c.bold('\ndocs target'));
      info(`target ${c.cyan(docs.target)}  scope ${docs.scope}  base ${docs.basePath}  ${docs.source === 'unavailable' ? c.yellow('(build-only)') : ''}`);
    }
    log(c.bold('\ngenerated sites'));
    if (!targets.length) { info('none generated yet'); return { action, target: docs?.target ?? null, sites: [] }; }
    for (const t of targets) reportFreshness(root, t);
    return { action, target: docs?.target ?? null, sites: targets.map((t) => label(t)) };
  }

  if (action === 'build' || action === 'deploy') {
    // Every site is tried, even after one fails; the run exits 1 if any did (buildSite sets it).
    const sites = targets.map((t) => buildSite(root, t, { npmOptional: action === 'deploy' }));
    const built = sites.filter((s) => s.built).length;
    if (action === 'deploy') {
      const platform = docs ? (docs.target === 'gitlab-pages' ? 'gitlab' : docs.target === 'github-pages' ? 'github' : null) : null;
      // Both arms say the same thing about what was built here; only a run where every site built ends on ✓.
      const all = built > 0 && built === sites.length;
      const here = all ? null : built ? `only ${built} of ${sites.length} sites built here` : 'nothing was built here';
      if (!platform || !platformReady(platform)) {
        hand(`no Pages platform/CLI — ${here ?? 'built locally only'}; commit + push so the CI workflow can publish (yad docs sync --wire)`);
      } else {
        (all ? ok : info)(`${here ? `${here}; ` : ''}deploy via the ${platform} Pages workflow on push (yad docs sync --wire installs it)`);
        if (docs?.basePath) info(`will publish under ${docs.basePath}`);
      }
    }
    return { action, built, sites };
  }

  if (action === 'sync') {
    if (sync === 'wire') return wirePages(root, docs);
    // check (default) + refresh both compute staleness; refresh additionally rebuilds.
    const registry = readJSON(path.join(root, PROJECT_FILES.reposRegistry), { repos: [] });
    // One row per site. `built` is null when no build was tried (a check, or a fresh site), so it never
    // reads as a failed build; a refresh that could not build a stale site exits 1, as a deploy does.
    const sites = [];
    for (const t of targets) {
      const s = freshness(root, t, registry);
      if (s.stale) {
        warn(`${label(t)} — ${c.yellow('stale')}: ${s.reasons.join('; ')}`);
        const b = sync === 'refresh' ? buildSite(root, t, { npmOptional: true }) : { built: null, error: null };
        sites.push({ site: label(t), stale: true, built: b.built, error: b.error });
      } else {
        ok(`${label(t)} ${c.dim('— fresh')}`);
        sites.push({ site: label(t), stale: false, built: null, error: null });
      }
    }
    const stale = sites.filter((s) => s.stale).length;
    const built = sites.filter((s) => s.built).length;
    if (stale && sync !== 'refresh') hand('regenerate content with the yad-docs / yad-docs-overview skill (the AI step), then `yad docs deploy`');
    return { action, sync, stale, built, sites };
  }

  fail(`unknown docs action: ${action} (list | build | deploy | sync)`);
  process.exitCode = 1;
  return { action };
}

// ---- helpers ------------------------------------------------------------------------------------
function enumerateSites(root) {
  const out = [];
  if (exists(siteDir(root, { overview: true }))) out.push({ overview: true });
  const epicsDir = path.join(root, 'epics');
  if (exists(epicsDir)) {
    for (const e of fs.readdirSync(epicsDir).sort()) {
      if (exists(path.join(epicsDir, e, 'docs-site'))) out.push({ epic: e });
    }
  }
  return out;
}
function label(t) { return t.overview ? 'overview (docs/sdlc-site)' : `epic ${t.epic}`; }

function freshness(root, t, registry) {
  const manifest = readJSON(manifestPath(root, t), null);
  if (t.overview) {
    // The overview is generated from the project pipeline definition, not an epic's artifacts. No shell
    // version: the overview is copied from the shell once and updated in place after that
    // (yad-docs-overview, Step 3), so a shell upgrade is not a reason to rebuild it.
    const files = ['skills/sdlc/config.yaml', 'skills/sdlc/module-help.csv', 'docs/diagrams/sdlc-overview.mmd']
      .map((f) => path.join(root, f)).filter(exists);
    return docsStale(manifest, { artifactHash: docsArtifactHash(files) });
  }
  const epicMeta = readJSON(path.join(root, 'epics', t.epic, '.sdlc/state.json'), {});
  const repos = epicMeta.repos || [];
  const surface = contractSurfaceHash(path.join(root, 'epics', t.epic)); // null when no locked surface
  return docsStale(manifest, {
    artifactHash: docsArtifactHash(docsArtifactFiles(root, t.epic), surface || ''),
    repoHeads: repoHeadsFor(root, repos, registry),
    shellVersion: shellVersion(),
  });
}
function reportFreshness(root, t) {
  const registry = readJSON(path.join(root, PROJECT_FILES.reposRegistry), { repos: [] });
  const s = freshness(root, t, registry);
  if (s.stale) warn(`${label(t)} — ${c.yellow('stale')}: ${s.reasons.join('; ')}`);
  else ok(`${label(t)} ${c.dim('— fresh')}`);
}

function wirePages(root, docs) {
  const platform = wiredPagesPlatform(docs);
  const rel = pagesWorkflowPath(platform);
  const dest = path.join(root, rel);
  fs.mkdirSync(path.dirname(dest), { recursive: true });
  fs.writeFileSync(dest, pagesWorkflow(platform));
  ok(`wired ${rel} ${c.dim(`(${platform} Pages)`)}`);
  if (platform === 'gitlab') hand(`include it from .gitlab-ci.yml:  include: { local: ${rel} }`);
  else hand('commit it; set the repo Pages source to "GitHub Actions" so it publishes on push');
  return { wired: rel };
}
